inline void thermo_ode_cp_h(
    const double T,
    double* __restrict__ cp_mole,
    double* __restrict__ h_mole
) noexcept {
    const double T2 = T * T;
    const double T3 = T2 * T;
    const double T4 = T2 * T2;
    const double inv_T = 1.0 / T;
    const double RT = R_GAS * T;
    for (std::size_t s = 0; s < 22; ++s) {
        const double* a = (T > T_MID[s]) ? NASA_HIGH[s] : NASA_LOW[s];
        const double cp_r = a[0] + a[1] * T + a[2] * T2 + a[3] * T3 + a[4] * T4;
        const double h_rt = a[0] + 0.5 * a[1] * T + (1.0 / 3.0) * a[2] * T2
                          + 0.25 * a[3] * T3 + 0.2 * a[4] * T4 + a[5] * inv_T;
        cp_mole[s] = cp_r * R_GAS;
        h_mole[s] = h_rt * RT;
    }
}

